import{fetchCohortJSON}from'./current-cohort-loader.js';
import{fitGroups092,hydrateCurrent092,currentStatistics092}from'./match-fit-092.js';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>Number.isFinite(n)?'$'+Math.round(n/1000)+'k':'See estimate',degree=o=>o.routes.some(r=>['college','graduate'].includes(r.key));let rows=[],filtered=[],page=0,expanded=false;
const labels={development:'Development',holdout:'Original holdout',holdout049:'Fresh holdout',holdout056:'Expansion holdout',grok075:'Grok evaluation'},route=o=>o.routes.some(r=>r.key==='graduate')?'Graduate':degree(o)?'Bachelor':o.routes.some(r=>r.key==='program')?'Certificate / associate':o.routes.some(r=>r.key==='apprenticeship')?'Apprenticeship':'No degree';
const career=o=>`<li><a class="fit-career" href="/results-board.html?model=${encodeURIComponent(currentModel)}">${h(o.title)}</a><div class="fit-meta"><strong>${money(o.entry)}</strong><span>${h(route(o))}</span><span class="support-chip ${o.candidate?'pending':o.top?'top':'supported'}" title="${o.candidate?'Specific interests need confirmation':o.top?'Supported Top match':'Supported alternative'}">${o.candidate?'Confirm':o.top?'Top':'Supported'}</span>${!Number.isFinite(o.correlation)?'<span>Unscored</span>':''}${o.mixedInterests?'<span class="conflict-chip">Mixed</span>':''}</div></li>`;let currentModel='';
function render(){const c=$('cohort').value,q=$('search').value.toLowerCase().trim(),s=$('status').value;filtered=rows.filter(r=>(c==='original'?r.cohort!=='grok075':r.cohort===c)&&(!q||[r.name,r.id,...r.supported.map(o=>o.title),...r.candidates.map(o=>o.title)].join(' ').toLowerCase().includes(q))&&(s==='all'||s==='noTop'&&!r.supported.some(o=>o.top)||s==='degree'&&r.supported.some(o=>o.top&&degree(o))||s==='noDegree'&&!r.supported.some(o=>o.top&&degree(o))));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/25)-1));const stats=currentStatistics092(filtered);$('totals').innerHTML=[['Students',stats.models],['Supported Top',stats.top],['College / graduate Top',stats.degree],['No-degree Top',stats.noncollege],['Supported lifestyle met',stats.lifestyle],['No supported Top',stats.models-stats.top]].map(([l,n],i)=>`<div><strong>${n}${i?`<small>${stats.models?(100*n/stats.models).toFixed(1):0}%</small>`:''}</strong><span>${l}</span></div>`).join('');$('students').innerHTML=filtered.slice(page*25,(page+1)*25).map(r=>{currentModel=r.id;const cover=r.supported.filter(o=>o.lifestyleCovers===true);return`<tr><td><a class="student-name" href="/results-board.html?model=${encodeURIComponent(r.id)}">${h(r.name)}</a><small>${h(r.id)}<br>${h(labels[r.cohort])}</small><a class="journey-link" href="/model-journey.html?model=${encodeURIComponent(r.id)}">View journey →</a></td>${fitGroups092(r).map(g=>`<td class="fit-level-cell ${g.id}">${g.offers.length?`<ul class="career-list">${(expanded?g.offers:g.offers.slice(0,3)).map(career).join('')}</ul>${!expanded&&g.offers.length>3?`<details class="more-fit"><summary>${g.offers.length-3} more</summary><ul class="career-list">${g.offers.slice(3).map(career).join('')}</ul></details>`:''}`:'<span class="empty-fit">—</span>'}</td>`).join('')}<td><b>${money(r.lifestyle.target)} target</b><p>${cover.length?`${cover.length} assessed option${cover.length===1?' meets':'s meet'} target`:!r.supported.length?'No supported match yet':r.supported.every(o=>o.lifestyleCovers===null)?'Not assessed':r.supported.some(o=>o.lifestyleCovers===null)?'Below target / unassessed':'Assessed options below target'}</p><a href="/results-board.html?model=${encodeURIComponent(r.id)}">Full results →</a></td></tr>`;}).join('')||'<tr><td colspan="6">No students match these filters.</td></tr>';$('page').textContent=`${filtered.length?page*25+1:0}–${Math.min((page+1)*25,filtered.length)} of ${filtered.length}`;$('prev').disabled=!page;$('next').disabled=(page+1)*25>=filtered.length;}
$('expand-all').onclick=()=>{expanded=!expanded;$('expand-all').setAttribute('aria-pressed',String(expanded));$('expand-all').textContent=expanded?'Collapse careers':'Expand all careers';render();};
for(const id of['cohort','status'])$(id).onchange=()=>{page=0;render();};$('search').oninput=()=>{page=0;render();};$('prev').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};$('download').onclick=()=>{const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';const csv=[['Student','ID','Cohort','Fit level','Career','Support','Education','Annual entry estimate','Lifestyle target'],...filtered.flatMap(r=>fitGroups092(r).flatMap(g=>g.offers.map(o=>[r.name,r.id,r.cohort,Number.isFinite(o.correlation)?g.label:'Unscored',o.title,o.candidate?'Needs confirmation':o.top?'Top':'Supported alternative',o.routes.map(r=>r.label).join('; '),o.entry,r.lifestyle.target])))].map(r=>r.map(cell).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='current-student-matches.csv';a.click();URL.revokeObjectURL(a.href);};
try{const data=await fetchCohortJSON('/developer/current-students-091.json.gz');rows=hydrateCurrent092(data);const p=new URL(location.href).searchParams;if(p.get('cohort')==='grok075'||p.get('researchCohort')==='grok075'||(p.get('model')||p.get('query')||'').startsWith('grok075-'))$('cohort').value='grok075';$('search').value=p.get('query')||p.get('model')||'';render();}catch(e){$('totals').textContent='Could not load current matches. Please reload.';console.error(e);}
